select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('archive-code','کد بایگانی','text',true,10,'{}'),('document-code','کد سند','text',true,20,'{}'),('document-title','عنوان سند','text',true,30,'{}'),('document-type','نوع سند','select',true,40,'{"options":["دستورالعمل","آیین‌نامه","فرآیند","راهنما","خط‌مشی","قرارداد","گزارش","صورتجلسه","فرم","سایر"]}'),('version','نسخه','text',false,50,'{}'),('archive-folder','محل بایگانی','text',true,60,'{}'),('retention-class','طبقه نگهداری','select',true,70,'{"options":["دائمی","بلندمدت","میان‌مدت","کوتاه‌مدت"]}'),('retention-until','تاریخ پایان نگهداری','text',false,80,'{}'),('confidentiality','سطح محرمانگی','select',true,90,'{"options":["عمومی","داخلی","محرمانه","بسیار محرمانه"]}'),('archive-reason','دلیل بایگانی','select',true,100,'{"options":["پایان اعتبار","جایگزینی نسخه","اتمام فرآیند","تصمیم سازمانی","نگهداری قانونی","سایر"]}'),('archive-date','تاریخ بایگانی','text',false,110,'{}'),('disposal-date','تاریخ امحای برنامه‌ریزی‌شده','text',false,120,'{}'),('disposal-method','روش امحا','select',false,130,'{"options":["حذف امن دیجیتال","امحای فیزیکی","تحویل به امحای مجاز","بدون امحا","سایر"]}'),('archive-status','وضعیت بایگانی','select',true,140,'{"options":["در انتظار بایگانی","بایگانی شده","در انتظار بررسی امحا","مجاز به امحا","امحا شده","بازگردانی شده","متوقف شده"]}'),('approved-by','تأییدکننده','text',false,150,'{}'),('approval-date','تاریخ تأیید','text',false,160,'{}'),('disposal-reference','مرجع امحا','text',false,170,'{}'),('description','توضیحات','textarea',false,180,'{}'),('notes','یادداشت','textarea',false,190,'{}')
) v(k,t,ft,r,s,o) where m.code='45-document-retention' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
