insert into platform_modules(code,title,is_active) values ('45-document-retention','بایگانی و امحای مستندات',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values
('read','مشاهده بایگانی','modules:45-document-retention:read'),('write','ثبت بایگانی','modules:45-document-retention:write'),('delete','حذف رکورد بایگانی','modules:45-document-retention:delete'),('archive','بایگانی کردن','modules:45-document-retention:archive'),('review','بررسی امحا','modules:45-document-retention:review'),('dispose','ثبت امحا','modules:45-document-retention:dispose'),('restore','بازگردانی سند','modules:45-document-retention:restore')) v(a,t,p) where m.code='45-document-retention' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;